contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 extra) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        address(this).balance;
        uint256 cBefore = address(c).balance;
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted ? address(c).balance == cBefore : address(c).balance == 0);
    }

    receive() external payable {}
}

